WITH stroke_admissions AS (
  -- Identify primary stroke admissions
  SELECT DISTINCT 
    p.subject_id,
    a.hadm_id,
    p.gender,
    p.anchor_age,
    a.admittime,
    a.dischtime,
    a.hospital_expire_flag,
    CASE WHEN a.dischtime IS NOT NULL THEN DATE_DIFF(a.dischtime, a.admittime, DAY) ELSE NULL END AS los_days
  FROM `physionet-data.mimiciv_3_1_hosp.patients` p
  INNER JOIN `physionet-data.mimiciv_3_1_hosp.admissions` a
    ON p.subject_id = a.subject_id
  INNER JOIN `physionet-data.mimiciv_3_1_hosp.diagnoses_icd` d
    ON a.hadm_id = d.hadm_id AND d.seq_num = 1
  WHERE p.gender = 'M'
    AND p.anchor_age BETWEEN 52 AND 62
    AND (
      -- ICD-9 stroke codes
      (d.icd_version = 9 AND d.icd_code LIKE 'I6%' AND d.icd_code NOT LIKE 'I67.8%')
      OR
      -- ICD-10 stroke codes
      (d.icd_version = 10 AND d.icd_code LIKE 'I6%')
    )
),
elixhauser_scores AS (
  -- Compute Elixhauser comorbidity score (van Walraven weights) per admission
  WITH elix_conditions AS (
    SELECT 
      sa.hadm_id,
      -- CHF (weight 7)
      MAX(CASE WHEN di.icd_code IN ('428.0', '428.1', '428.2', '428.3', '428.4', '428.9', '397.0', '398.91', '422.0', '422.5', '422.7', '422.8', '425.4', '425.5', '425.7', '425.8', 'I09.9', 'I11.0', 'I13.0', 'I13.2', 'I25.5', 'I42.0', 'I42.5', 'I42.6', 'I42.7', 'I42.8', 'I42.9', 'I43.0', 'I43.1', 'I43.2', 'P29.0') THEN 1 ELSE 0 END) AS chf,
      -- Cardiac Arrhythmias (weight -2)
      MAX(CASE WHEN di.icd_code IN ('427.31', '427.32', '427.34', '427.41', '427.42', '427.60', '427.61', '427.69', '785.0', 'I47.0', 'I47.1', 'I47.2', 'I48', 'I49.02', 'I49.5', 'I49.8', 'I49.9', 'R00.1', 'T82.897A') THEN 1 ELSE 0 END) AS arrhythmia,
      -- Valvular disease (weight 0)
      MAX(CASE WHEN di.icd_code IN ('394.0', '394.1', '394.2', '394.9', '395.0', '395.1', '395.2', '395.9', '396.0', '396.1', '396.2', '396.8', '396.9', '397.0', '397.1', '397.9', '424.0', '424.1', '424.2', '424.3', '424.90', '424.91', '424.99', 'V42.2', 'Z95.2', 'Z95.3', 'Z95.4', 'I05.0', 'I05.1', 'I05.2', 'I05.8', 'I05.9', 'I06.0', 'I06.1', 'I06.2', 'I06.8', 'I06.9', 'I07.0', 'I07.1', 'I07.2', 'I07.8', 'I07.9', 'I08.0', 'I08.1', 'I08.3', 'I08.9', 'I09.1', 'I09.8', 'I34.0', 'I34.1', 'I34.2', 'I34.8', 'I34.9', 'I35.0', 'I35.1', 'I35.2', 'I35.8', 'I35.9', 'I36.0', 'I36.1', 'I36.2', 'I36.8', 'I36.9', 'I37.0', 'I37.1', 'I37.2', 'I37.8', 'I37.9', 'I38', 'Q23.0', 'Q23.1', 'Q23.2', 'Q23.3', 'Q23.4', 'T82.817A', 'T82.857A', 'T82.897A', 'Z95.2', 'Z95.3', 'Z95.4') THEN 1 ELSE 0 END) AS valvular,
      -- Pulmonary circulation disorders (weight 3)
      MAX(CASE WHEN di.icd_code IN ('415.0', '416.0', '416.1', '416.8', '416.9', '417.0', '417.8', '417.9', '506.4', '508.8', 'I26.01', 'I26.02', 'I26.09', 'I26.90', 'I26.92', 'I26.93', 'I26.94', 'I26.99', 'I27.0', 'I27.1', 'I27.20', 'I27.21', 'I27.22', 'I27.23', 'I27.24', 'I27.29', 'I27.81', 'I27.83', 'I27.89', 'I27.9', 'I28.0', 'I28.1', 'I28.8', 'I28.9') THEN 1 ELSE 0 END) AS pulm_circ,
      -- Peripheral vascular disorders (weight 2)
      MAX(CASE WHEN di.icd_code IN ('250.7', '443.9', '447.1', '557.1', '557.9', 'V43.4', 'E10.52', 'E10.53', 'E11.52', 'E11.53', 'E13.52', 'E13.53', 'I70.0', 'I70.2', 'I70.3', 'I70.4', 'I70.5', 'I70.6', 'I70.7', 'I70.8', 'I70.9', 'I73.9', 'K55.1', 'K55.8', 'K55.9', 'L94.0', 'L95.1', 'M31.4', 'T82.3', 'T82.5', 'Z95.9') THEN 1 ELSE 0 END) AS pvd,
      -- Hypertension uncomplicated (weight 0)
      MAX(CASE WHEN di.icd_code IN ('401.1', '401.9', 'Hypertension, essential, benign', 'Hypertension, essential, unspecified') THEN 1 ELSE 0 END) AS htn,
      -- Hypertension complicated (weight 0)
      MAX(CASE WHEN di.icd_code IN ('401.0', '404.0', '404.1', '404.9', '405.0', '405.1', '405.9', '402.0', '402.1', '402.9', '403.0', '403.1', '403.9', 'I10', 'I11.9', 'I12.9', 'I13.10', 'I13.11', 'I13.12', 'I13.19', 'I15.0', 'I15.1', 'I15.2', 'I15.8', 'I15.9', 'I16.0', 'I16.1', 'I16.9') THEN 1 ELSE 0 END) AS htn_cx,
