      MAX(CASE WHEN di.icd_code IN ('292.0', '292.82', '292.83', '292.84', '292.89', '304.00', '304.01', '304.02', '304.10', '304.11', '304.12', '304.20', '304.21', '304.22', '304.30', '304.31', '304.32', '304.40', '304.41', '304.42', '304.50', '304.51', '304.52', '304.60', '304.61', '304.62', '304.70', '304.71', '304.72', '304.80', '304.81', '304.82', '304.90', '304.91', '304.92', '305.2', '305.20', '305.21', '305.22', '305.3', '305.30', '305.31', '305.32', '305.4', '305.40', '305.41', '305.42', '305.5', '305.50', '305.51', '305.52', '305.6', '305.60', '305.61', '305.62', '305.8', '305.80', '305.81', '305.82', '305.9', '305.90', '305.91', '305.92', 'V11.1', 'F11.10', 'F11.120', 'F11.121', 'F11.129', 'F11.14', 'F11.150', 'F11.151', 'F11.159', 'F11.181', 'F11.182', 'F11.188', 'F11.19', 'F12.10', 'F12.120', 'F12.121', 'F12.129', 'F12.150', 'F12.151', 'F12.159', 'F12.180', 'F12.181', 'F12.182', 'F12.188', 'F12.19', 'F12.20', 'F12.220', 'F12.221', 'F12.229', 'F12.250', 'F12.251', 'F12.259', 'F12.280', 'F12.281', 'F12.282', 'F12.288', 'F12.29', 'F12.90', 'F12.950', 'F12.951', 'F12.959', 'F13.10', 'F13.120', 'F13.121', 'F13.129', 'F13.14', 'F13.150', 'F13.151', 'F13.159', 'F13.180', 'F13.181', 'F13.182', 'F13.188', 'F13.19', 'F13.20', 'F13.220', 'F13.221', 'F13.229', 'F13.24', 'F13.250', 'F13.251', 'F13.259', 'F13.280', 'F13.281', 'F13.282', 'F13.288', 'F13.29', 'F13.90', 'F13.920', 'F13.921', 'F13.929', 'F13.94', 'F13.950', 'F13.951', 'F13.959', 'F13.980', 'F13.981', 'F13.982', 'F13.988', 'F13.99', 'F14.10', 'F14.120', 'F14.121', 'F14.129', 'F14.14', 'F14.150', 'F14.151', 'F14.159', 'F14.180', 'F14.181', 'F14.182', 'F14.188', 'F14.19', 'F14.20', 'F14.220', 'F14.221', 'F14.229', 'F14.24', 'F14.250', 'F14.251', 'F14.259', 'F14.280', 'F14.281', 'F14.282', 'F14.288', 'F14.29', 'F14.90', 'F14.940', 'F14.941', 'F14.949', 'F14.950', 'F14.951', 'F14.959', 'F14.980', 'F14.981', 'F14.982', 'F14.988', 'F14.99', 'F15.10', 'F15.120', 'F15.121', 'F15.129', 'F15.14', 'F15.150', 'F15.151', 'F15.159', 'F15.180', 'F15.181', 'F15.182', 'F15.188', 'F15.19', 'F15.20', 'F15.220', 'F15.221', 'F15.229', 'F15.24', 'F15.250', 'F15.251', 'F15.259', 'F15.280', 'F15.281', 'F15.282', 'F15.288', 'F15.29', 'F15.90', 'F15.920', 'F15.921', 'F15.929', 'F15.94', 'F15.950', 'F15.951', 'F15.959', 'F15.980', 'F15.981', 'F15.982', 'F15.988', 'F15.99', 'F16.10', 'F16.14', 'F16.183', 'F16.19', 'F16.20', 'F16.24', 'F16.283', 'F16.29', 'F16.90', 'F16.94', 'F16.983', 'F16.99', 'F18.10', 'F18.120', 'F18.121', 'F18.129', 'F18.14', 'F18.150', 'F18.151', 'F18.159', 'F18.17', 'F18.180', 'F18.181', 'F18.182', 'F18.188', 'F18.19', 'F18.20', 'F18.22', 'F18.24', 'F18.27', 'F18.28', 'F18.29', 'F18.90', 'F18.92', 'F18.94', 'F18.97', 'F18.98', 'F18.99', 'F19.10', 'F19.120', 'F19.121', 'F19.129', 'F19.14', 'F19.150', 'F19.151', 'F19.159', 'F19.16', 'F19.17', 'F19.180', 'F19.181', 'F19.182', 'F19.188', 'F19.19', 'F19.20', 'F19.22', 'F19.24', 'F19.27', 'F19.28', 'F19.29', 'F19.90', 'F19.92', 'F19.94', 'F19.97', 'F19.98', 'F19.99') THEN 1 ELSE 0 END) AS drug,
      -- Psychoses (weight 0)
      MAX(CASE WHEN di.icd_code IN ('295.0', '295.1', '295.2', '295.3', '295.4', '295.5', '295.6', '295.7', '295.8', '295.9', '296.0', '296.1', '296.8', '297.0', '297.1', '297.3', '297.8', '297.9', '298.8', '298.9', '299.1', '299.9', 'F20.0', 'F20.1', 'F20.2', 'F20.3', 'F20.5', 'F20.6', 'F20.8', 'F20.9', 'F22', 'F23', 'F24', 'F25.0', 'F25.1', 'F25.2', 'F25.8', 'F25.9', 'F28', 'F29', 'F30.2', 'F30.8', 'F30.9', 'F31.2', 'F31.3', 'F31.5', 'F31.9') THEN 1 ELSE 0 END) AS psychoses,
      -- Depression (weight 0)
      MAX(CASE WHEN di.icd_code IN ('296.2', '296.3', '296.5', '300.4', '301.12', '309.0', '309.1', '311', 'F32.0', 'F32.1', 'F32.2', 'F32.3', 'F32.4', 'F32.5', 'F32.8', 'F32.9', 'F33.0', 'F33.1', 'F33.2', 'F33.3', 'F33.4', 'F33.40', 'F33.41', 'F33.42', 'F33.8', 'F33.9', 'F34.1') THEN 1 ELSE 0 END) AS depression
    FROM stroke_admissions sa
    LEFT JOIN `physionet-data.mimiciv_3_1_hosp.diagnoses_icd` di
      ON sa.hadm_id = di.hadm_id
    LEFT JOIN `physionet-data.mimiciv_3_1_hosp.procedures_icd` pi
      ON sa.hadm_id = pi.hadm_id
    GROUP BY sa.hadm_id
  )
  SELECT 
    sa.*,
    (ec.chf * 7 +
     ec.arrhythmia * -2 +
     ec.valvular * 0 +
     ec.pulm_circ * 3 +
     ec.pvd * 2 +
     ec.htn * 0 +
     ec.htn_cx * 0 +
     ec.paralysis * 4 +
     ec.neuro_other * 3 +
     ec.cpd * 3 +
     ec.diabetes * 0 +
     ec.diabetes_cx * 2 +
     ec.hypo_thyroid * 0 +
     ec.renal * 5 +
     ec.liver * 3 +
     ec.cancer * 6 +
     ec.metastatic_cancer * 7 +
     ec.coagulopathy * 4 +
     ec.obesity * 0 +
     ec.weight_loss * 5 +
     ec.fluid_electrolyte * 3 +
     ec.blood_loss_anemia * 3 +
     ec.deficiency_anemia * 0 +
     ec.alcohol * -2 +
     ec.drug * -2 +
     ec.psychoses * 0 +
     ec.depression * 0) AS elix_score
  FROM stroke_admissions sa
  INNER JOIN elix_conditions ec
    ON sa.hadm_id = ec.hadm_id
),
ckd_diabetes AS (
  -- Flag CKD and diabetes per admission
  SELECT 
    es.*,
    MAX(CASE WHEN di.icd_code IN ('585.1', '585.2', '585.3', '585.4', '585.5', '585.6', '585.9', '586', 'V42.0', 'V45.11', 'V56.0', 'V56.1', 'V56.2', 'V56.8', 'N18.1', 'N18.2', 'N18.3', 'N18.4', 'N18.5', 'N18.6', 'N19') THEN 1 ELSE 0 END) AS has_ckd,
    MAX(CASE WHEN di.icd_code LIKE '250.%' OR di.icd_code LIKE 'E1[0-4].%' THEN 1 ELSE 0 END) AS has_diabetes
  FROM elixhauser_scores es
  LEFT JOIN `physionet-data.mimiciv_3_1_hosp.diagnoses_icd` di
    ON es.hadm_id = di.hadm_id
  GROUP BY es.subject_id, es.hadm_id, es.gender, es.anchor_age, es.admittime, es.dischtime, es.hospital_expire_flag, es.los_days, es.elix_score
),
icu_flags AS (
  -- Flag ICU vs non-ICU
  SELECT 
    cd.*,
    CASE WHEN EXISTS (
      SELECT 1 FROM `physionet-data.mimiciv_3_1_hosp.transfers` t 
      WHERE t.hadm_id = cd.hadm_id 
        AND t.careunit NOT IN ('Discharge', 'Regular Floor') 
        AND t.careunit IS NOT NULL
    ) THEN 'ICU' ELSE 'Non-ICU' END AS icu_status
  FROM ckd_diabetes cd
),
stratified AS (
  -- Stratify LOS and tertiles
  SELECT 
    *,
    CASE 
      WHEN los_days <= 5 THEN 'LOS <=5'
      WHEN los_days > 5 THEN 'LOS >5'
      ELSE 'LOS <=5'  -- Handle NULL/0 as <=5
    END AS los_stratum,
    NTILE(3) OVER (ORDER BY elix_score) AS comorbidity_tertile
  FROM icu_flags
)
-- Aggregate outcomes
SELECT 
  icu_status,
  los_stratum,
  comorbidity_tertile,
  COUNT(*) AS num_admissions,
  ROUND(SUM(CAST(hospital_expire_flag AS INT64)) * 100.0 / COUNT(*), 2) AS mortality_pct,
  ROUND(SUM(CAST(has_ckd AS INT64)) * 100.0 / COUNT(*), 2) AS ckd_prevalence_pct,
  ROUND(SUM(CAST(has_diabetes AS INT64)) * 100.0 / COUNT(*), 2) AS diabetes_prevalence_pct
FROM stratified
GROUP BY icu_status, los_stratum, comorbidity_tertile
ORDER BY icu_status, los_stratum, comorbidity_tertile;